log.info(message);
res.status(404).send(message);
}

function register(router) {


router.all('/custom/:path*', (req, res, next) => {
cls.namespace.bindEmitter(req);
cls.namespace.bindEmitter(res);

cls.init(() => handleRequest(req, res));
});
}

module.exports = {
register
};

